args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?dir ?dirLabel WHERE {
  VALUES ?film { dbr:Felices_140 dbr:Dr._Who_and_the_Daleks }
  OPTIONAL { ?film dbo:director ?dir }
  OPTIONAL { ?film dbp:director ?dir }
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER(lang(?filmLabel)='en') }
  OPTIONAL { ?dir rdfs:label ?dirLabel FILTER(lang(?dirLabel)='en') }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?director ?directorLabel ?birthDate WHERE {
  VALUES ?director { dbr:Gordon_Flemyng dbr:Gracia_Querejeta }
  OPTIONAL { ?director dbo:birthDate ?birthDate }
  OPTIONAL { ?director dbp:birthDate ?birthDate }
  OPTIONAL { ?director dbp:born ?birthDate }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel)='en') }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?laterFilm ?laterFilmLabel ?dLater ?bLater WHERE {
  BIND(dbr:Felices_140 AS ?f1)
  BIND(dbr:Dr._Who_and_the_Daleks AS ?f2)
  BIND(dbr:Gracia_Querejeta AS ?d1)
  BIND(dbr:Gordon_Flemyng AS ?d2)

  ?d1 dbo:birthDate ?b1 .
  ?d2 dbo:birthDate ?b2 .

  {
    FILTER(?b1 > ?b2)
    BIND(?f1 AS ?laterFilm)
    BIND(?d1 AS ?dLater)
    BIND(?b1 AS ?bLater)
  } UNION {
    FILTER(?b2 > ?b1)
    BIND(?f2 AS ?laterFilm)
    BIND(?d2 AS ?dLater)
    BIND(?b2 AS ?bLater)
  }

  OPTIONAL { ?laterFilm rdfs:label ?laterFilmLabel FILTER(lang(?laterFilmLabel)='en') }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?birthDate WHERE {
  VALUES ?film { dbr:Felices_140 dbr:Dr._Who_and_the_Daleks }
  ?film dbo:director ?director .
  ?director dbo:birthDate ?birthDate .
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER(lang(?filmLabel)='en') }
} ORDER BY DESC(?birthDate) LIMIT 1

